    CreatePresetRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the preset.</p>"}))
    CreatePresetRequest.add_member(:container, Smithy::Schema::Shapes::ShapeRef.new(shape: PresetContainer, location_name: 'Container', traits: {"smithy.api#documentation" => "<p>The container type for the output file. Valid values include <code>flac</code>,\n            <code>flv</code>, <code>fmp4</code>, \n            <code>gif</code>, <code>mp3</code>, \n            <code>mp4</code>, <code>mpg</code>, <code>mxf</code>, <code>oga</code>, \n            <code>ogg</code>, <code>ts</code>, and <code>webm</code>.</p>", "smithy.api#required" => {}}))
    CreatePresetRequest.add_member(:video, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoParameters, location_name: 'Video', traits: {"smithy.api#documentation" => "<p>A section of the request body that specifies the video parameters.</p>"}))
    CreatePresetRequest.add_member(:audio, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioParameters, location_name: 'Audio', traits: {"smithy.api#documentation" => "<p>A section of the request body that specifies the audio parameters.</p>"}))
    CreatePresetRequest.add_member(:thumbnails, Smithy::Schema::Shapes::ShapeRef.new(shape: Thumbnails, location_name: 'Thumbnails', traits: {"smithy.api#documentation" => "<p>A section of the request body that specifies the thumbnail parameters, if any.</p>"}))
    CreatePresetRequest.type = Types::CreatePresetRequest
    CreatePresetResponse.add_member(:preset, Smithy::Schema::Shapes::ShapeRef.new(shape: Preset, location_name: 'Preset', traits: {"smithy.api#documentation" => "<p>A section of the response body that provides information about the preset that is created.</p>"}))
    CreatePresetResponse.add_member(:warning, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Warning', traits: {"smithy.api#documentation" => "<p>If the preset settings don't comply with the standards for the video codec but Elastic Transcoder \n            created the preset, this message explains the reason the preset settings don't meet the \n            standard. Elastic Transcoder created the preset because the settings might produce \n            acceptable output.</p>"}))
