    ListJobsByStatusRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: JobStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>To get information about all of the jobs associated with the current AWS account that\n            have a given status, specify the following status: <code>Submitted</code>,\n                <code>Progressing</code>, <code>Complete</code>, <code>Canceled</code>, or\n                <code>Error</code>.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
