    ReadPipelineResponse.add_member(:warnings, Smithy::Schema::Shapes::ShapeRef.new(shape: Warnings, location_name: 'Warnings', traits: {"smithy.api#documentation" => "<p>Elastic Transcoder returns a warning if the resources used by your pipeline are not in the same region \n            as the pipeline.</p>\n        <p>Using resources in the same region, such as your Amazon S3 buckets, Amazon SNS notification topics, \n            and AWS KMS key, reduces processing time and prevents cross-regional charges.</p>"}))
