    TestRoleRequest.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The IAM Amazon Resource Name (ARN) for the role that you want Elastic Transcoder to test.</p>", "smithy.api#required" => {}}))
    TestRoleRequest.add_member(:input_bucket, Smithy::Schema::Shapes::ShapeRef.new(shape: BucketName, location_name: 'InputBucket', traits: {"smithy.api#documentation" => "<p>The Amazon S3 bucket that contains media files to be transcoded. The action attempts to read from this bucket.</p>", "smithy.api#required" => {}}))
    TestRoleRequest.add_member(:output_bucket, Smithy::Schema::Shapes::ShapeRef.new(shape: BucketName, location_name: 'OutputBucket', traits: {"smithy.api#documentation" => "<p>The Amazon S3 bucket that Elastic Transcoder writes transcoded media files to. The action attempts to read from this bucket.</p>", "smithy.api#required" => {}}))
    TestRoleRequest.add_member(:topics, Smithy::Schema::Shapes::ShapeRef.new(shape: SnsTopics, location_name: 'Topics', traits: {"smithy.api#documentation" => "<p>The ARNs of one or more Amazon Simple Notification Service (Amazon SNS) topics that you want the action to send a test notification to.</p>", "smithy.api#required" => {}}))
