    TestRoleResponse.add_member(:messages, Smithy::Schema::Shapes::ShapeRef.new(shape: ExceptionMessages, location_name: 'Messages', traits: {"smithy.api#documentation" => "<p>If the <code>Success</code> element contains <code>false</code>, this value is an array\n            of one or more error messages that were generated during the test process.</p>"}))
