    Warning.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Message', traits: {"smithy.api#documentation" => "<p>The message explaining what resources are in a different region from the pipeline.</p>\n        <note>\n            <p>AWS KMS keys must be in the same region as the pipeline.</p>\n         </note>"}))
